--
-- Table structure for table `disponibilidad_docentes`
--

DROP TABLE IF EXISTS `disponibilidad_docentes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `disponibilidad_docentes` (
  `id_disponibilidad` int NOT NULL AUTO_INCREMENT,
  `id_docente` int NOT NULL,
  `dia_semana` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  `estado` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A',
  `fecha_modificacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `usuario_modificacion` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'sistema',
  PRIMARY KEY (`id_disponibilidad`),
  KEY `fk_disponibilidad_docente` (`id_docente`),
  CONSTRAINT `fk_disponibilidad_docente` FOREIGN KEY (`id_docente`) REFERENCES `docentes` (`id_docente`) ON DELETE CASCADE,
  CONSTRAINT `chk_disponibilidad_estado` CHECK ((`estado` in (_utf8mb4'A',_utf8mb4'I',_utf8mb4'V'))),
  CONSTRAINT `chk_disponibilidad_horas` CHECK ((`hora_fin` > `hora_inicio`))
) ENGINE=InnoDB AUTO_INCREMENT=247 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

